const fs = require('fs');
const data = fs.readFileSync(0);
let pos = 0;

function nextInt() {
  while (pos < data.length && data[pos] <= 32) pos++;
  let value = 0;
  while (pos < data.length && data[pos] > 32) {
    value = value * 10 + data[pos] - 48;
    pos++;
  }
  return value;
}

const N = nextInt();
const Q = nextInt();
const K = nextInt();

const A = new Float64Array(N + 1);
const X = new Float64Array(N + 1);
const Y = new Float64Array(N + 1);
const occX = new Map();
const occY = new Map();

for (let i = 1; i <= N; i++) {
  A[i] = nextInt();
  X[i] = A[i] + i;
  Y[i] = A[i] - i;

  let list = occX.get(X[i]);
  if (list === undefined) occX.set(X[i], list = []);
  list.push(i);

  list = occY.get(Y[i]);
  if (list === undefined) occY.set(Y[i], list = []);
  list.push(i);
}

const deletions = new Int32Array(Q + 1);
const deleted = new Uint8Array(N + 1);
for (let t = 1; t <= Q; t++) {
  deletions[t] = nextInt();
  deleted[deletions[t]] = 1;
}

function lowerBound(arr, value) {
  let left = 0;
  let right = arr.length;
  while (left < right) {
    const mid = (left + right) >>> 1;
    if (arr[mid] < value) left = mid + 1;
    else right = mid;
  }
  return left;
}

function upperBound(arr, value) {
  let left = 0;
  let right = arr.length;
  while (left < right) {
    const mid = (left + right) >>> 1;
    if (arr[mid] <= value) left = mid + 1;
    else right = mid;
  }
  return left;
}

function countRange(map, key, low, high) {
  if (low > high) return 0;
  const arr = map.get(key);
  if (arr === undefined) return 0;
  return upperBound(arr, high) - lowerBound(arr, low);
}

const parent = new Int32Array(N + 1);
const size = new Int32Array(N + 1);
const leftEnd = new Int32Array(N + 1);
const rightEnd = new Int32Array(N + 1);
const active = new Uint8Array(N + 1);

function find(x) {
  let root = x;
  while (parent[root] !== root) root = parent[root];
  while (parent[x] !== x) {
    const next = parent[x];
    parent[x] = root;
    x = next;
  }
  return root;
}

function crossPairs(leftRoot, rightRoot) {
  const l = leftEnd[leftRoot];
  const m = rightEnd[leftRoot];
  const r = rightEnd[rightRoot];
  let result = 0;

  if (size[leftRoot] <= size[rightRoot]) {
    for (let i = l; i <= m; i++) {
      const highX = Math.min(r, i + K);
      result += countRange(occX, X[i] + K, m + 1, highX);

      const highY = Math.min(r, i + K - 1);
      result += countRange(occY, Y[i] - K, m + 1, highY);
    }
  } else {
    const rightStart = m + 1;
    for (let i = rightStart; i <= r; i++) {
      const lowX = Math.max(l, i - K);
      result += countRange(occX, X[i] - K, lowX, m);

      const lowY = Math.max(l, i - K + 1);
      result += countRange(occY, Y[i] + K, lowY, m);
    }
  }
  return result;
}

let total = 0;

function unite(a, b) {
  let ra = find(a);
  let rb = find(b);
  if (ra === rb) return;

  if (leftEnd[ra] > leftEnd[rb]) {
    const tmp = ra;
    ra = rb;
    rb = tmp;
  }

  total += crossPairs(ra, rb);

  if (size[ra] < size[rb]) {
    const tmp = ra;
    ra = rb;
    rb = tmp;
  }

  parent[rb] = ra;
  size[ra] += size[rb];
  leftEnd[ra] = Math.min(leftEnd[ra], leftEnd[rb]);
  rightEnd[ra] = Math.max(rightEnd[ra], rightEnd[rb]);
}

function activate(x) {
  active[x] = 1;
  parent[x] = x;
  size[x] = 1;
  leftEnd[x] = x;
  rightEnd[x] = x;

  if (x > 1 && active[x - 1]) unite(x, x - 1);
  if (x < N && active[x + 1]) unite(x, x + 1);
}

for (let i = 1; i <= N; i++) {
  if (!deleted[i]) activate(i);
}

const answers = new Array(Q + 1);
answers[Q] = total;

for (let t = Q; t >= 1; t--) {
  activate(deletions[t]);
  answers[t - 1] = total;
}

console.log(answers.join('\n'));
